begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
select has_table('public','learning_speech','Speech rows exist');
select has_function('public','begin_speech_upload',array['uuid','uuid','uuid','text','text','bigint','text'],'Owner upload admission exists');
select has_function('public','claim_speech_job',array[]::text[],'Speech worker claim exists');
select has_function('public','checkpoint_speech_prompt',array['uuid','uuid','text','text'],'Prompt checkpoint exists');
insert into auth.users(id,email) values ('24000000-0000-4000-8000-000000000001','speech-owner@example.test'),('24000000-0000-4000-8000-000000000002','speech-other@example.test');
insert into learning_workspaces(id,user_id,title,kind) values('24000000-0000-4000-8000-000000000003','24000000-0000-4000-8000-000000000001','Speech','SPEAKING');
create temporary table speech_fixture(k text primary key,v jsonb);
grant all on speech_fixture to authenticated,service_role;
set local role authenticated;
select set_config('request.jwt.claim.sub','24000000-0000-4000-8000-000000000001',true);
insert into speech_fixture values('upload',begin_speech_upload('24000000-0000-4000-8000-000000000004','24000000-0000-4000-8000-000000000003',null,'I went home.','audio/webm',100,repeat('a',64)));
select ok(not ((select v from speech_fixture where k='upload') ?| array['storage_path','input','content_sha256','lease_token']),'Upload response hides private bindings');
select is(begin_speech_upload('24000000-0000-4000-8000-000000000004','24000000-0000-4000-8000-000000000003',null,'I went home.','audio/webm',100,repeat('a',64)),(select v from speech_fixture where k='upload'),'Identical upload replay is idempotent');
select throws_ok($$select begin_speech_upload('24000000-0000-4000-8000-000000000004','24000000-0000-4000-8000-000000000003',null,'I went home.','audio/webm',100,repeat('b',64))$$,'P0001','LEARNING_CONFLICT','Upload ID binds exact content hash');
select throws_ok($$select queue_speech_recording('24000000-0000-4000-8000-000000000004')$$,'P0001','LEARNING_INVALID','Cannot queue without object');
select throws_ok($$select storage_path from learning_speech$$,'42501',null,'Browser cannot select private paths');
select throws_ok($$update learning_speech set status='READY'$$,'42501',null,'Browser cannot mutate speech table');
select throws_ok($$select claim_speech_job()$$,'42501',null,'Browser cannot claim workers');
select throws_ok($$insert into storage.objects(bucket_id,name,metadata) values('learning-audio','24000000-0000-4000-8000-000000000001/24000000-0000-4000-8000-000000000004/recording','{"size":101,"mimetype":"audio/webm"}')$$,'42501',null,'Upload size mutation denied');
select ok(speech_storage_allowed('24000000-0000-4000-8000-000000000001/24000000-0000-4000-8000-000000000004/recording',null,true),'Storage preflight may omit metadata before bytes arrive');
select ok(speech_storage_allowed('24000000-0000-4000-8000-000000000001/24000000-0000-4000-8000-000000000004/recording','{"contentLength":100,"mimetype":"audio/webm"}',true),'Storage preflight contentLength matches admitted upload');
select lives_ok($$insert into storage.objects(bucket_id,name,metadata) values('learning-audio','24000000-0000-4000-8000-000000000001/24000000-0000-4000-8000-000000000004/recording','{"size":100,"mimetype":"audio/webm"}')$$,'Matching owner upload admitted');
select is(queue_speech_recording('24000000-0000-4000-8000-000000000004')->>'status','QUEUED','Explicit queue admits uploaded recording');
select is(queue_speech_recording('24000000-0000-4000-8000-000000000004')->>'status','QUEUED','Queue replay is idempotent');
with changed as (update storage.objects set metadata='{}' where bucket_id='learning-audio' returning id) select is(count(*),0::bigint,'Queued audio cannot be overwritten') from changed;
select set_config('request.jwt.claim.sub','24000000-0000-4000-8000-000000000002',true);
select is((select count(id) from learning_speech),0::bigint,'RLS hides other owners');
select is((select count(*) from storage.objects where bucket_id='learning-audio'),0::bigint,'Storage hides other owners');
select throws_ok($$select speech_audio_path('24000000-0000-4000-8000-000000000004')$$,'P0001','LEARNING_NOT_FOUND','Audio lookup checks owner');
select throws_ok($$select queue_speech_recording('24000000-0000-4000-8000-000000000004')$$,'P0001','LEARNING_NOT_FOUND','Queue checks owner');
reset role;
set local role service_role;
insert into speech_fixture values('claim',claim_speech_job());
select is(claim_speech_job(),null::jsonb,'Live lease cannot be claimed twice');
select is(finish_speech_job('24000000-0000-4000-8000-000000000004',gen_random_uuid(),null,'PROVIDER_ERROR'),false,'Wrong lease completion discarded');
select throws_ok($$select finish_speech_job('24000000-0000-4000-8000-000000000004',(select (v->>'lease_token')::uuid from speech_fixture where k='claim'),'{}',null)$$,'P0001','LEARNING_INVALID','Malformed completion rejected');
reset role;
update learning_speech set lease_expires_at=clock_timestamp()-interval '1 second';
set local role service_role;
select is(finish_speech_job('24000000-0000-4000-8000-000000000004',(select (v->>'lease_token')::uuid from speech_fixture where k='claim'),null,'PROVIDER_ERROR'),false,'Expired lease completion discarded');
update speech_fixture set v=claim_speech_job() where k='claim';
select is((select v->>'attempts' from speech_fixture where k='claim'),'2','Reclaim increments attempts');
insert into speech_fixture values('output','{"referenceText":"I went home.","originalText":"I goed home.","feedback":{"summary":"Use past tense.","corrections":[{"original":"goed","revised":"went","reason":"Irregular verb"}],"expressions":[],"nextPrompt":""},"storagePath":"24000000-0000-4000-8000-000000000001/24000000-0000-4000-8000-000000000004/recording","mimeType":"audio/webm","durationSeconds":4}');
select ok(finish_speech_job('24000000-0000-4000-8000-000000000004',(select (v->>'lease_token')::uuid from speech_fixture where k='claim'),(select v from speech_fixture where k='output'),null),'Valid structured completion accepted');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','24000000-0000-4000-8000-000000000001',true);
select learning_speech_command(jsonb_build_object('action','EDIT','requestId',gen_random_uuid(),'id','24000000-0000-4000-8000-000000000004','text','I went home.'));
select is((select original_text from learning_speech),'I goed home.','Editing preserves original transcript');
select learning_speech_command(jsonb_build_object('action','KEEP','requestId',gen_random_uuid(),'id','24000000-0000-4000-8000-000000000004','keep',true));
reset role;
update learning_speech set expires_at=clock_timestamp()-interval '1 day';
set local role service_role;
select ok(not exists(select 1 from jsonb_array_elements(speech_cleanup_candidates()) x where x->>'id'='24000000-0000-4000-8000-000000000004'),'KEEP wins before cleanup reservation');
reset role;
set local role authenticated;
select learning_speech_command(jsonb_build_object('action','KEEP','requestId',gen_random_uuid(),'id','24000000-0000-4000-8000-000000000004','keep',false));
reset role;
set local role service_role;
select ok(exists(select 1 from jsonb_array_elements(speech_cleanup_candidates()) x where x->>'id'='24000000-0000-4000-8000-000000000004'),'Expired unkept audio reserved for cleanup');
reset role;
set local role authenticated;
select throws_ok($$select learning_speech_command(jsonb_build_object('action','KEEP','requestId',gen_random_uuid(),'id','24000000-0000-4000-8000-000000000004','keep',true))$$,'P0001','LEARNING_CONFLICT','KEEP cannot race a reserved deletion');
reset role;
set local role service_role;
select ok(finish_speech_cleanup('24000000-0000-4000-8000-000000000004'),'Cleanup finalization accepted');
select ok(exists(select 1 from jsonb_array_elements(speech_cleanup_candidates()) x where x->>'id'='24000000-0000-4000-8000-000000000004'),'Late or remaining object is offered again after cleanup');
reset role;
set local role authenticated;
select is((select original_text from learning_speech),'I goed home.','Audio expiration retains transcript');
insert into speech_fixture values('prompt',jsonb_build_object('action','PROMPT','requestId',gen_random_uuid(),'id','24000000-0000-4000-8000-000000000005','workspaceId','24000000-0000-4000-8000-000000000003','level','EASY','topic','Travel'));
select learning_speech_command((select v from speech_fixture where k='prompt'));
select learning_speech_command((select v from speech_fixture where k='prompt'));
select is((select count(id) from learning_speech where kind='PROMPT'),1::bigint,'Prompt request replay does not duplicate');
reset role;
set local role service_role;
update speech_fixture set v=claim_speech_job() where k='claim';
select is(checkpoint_speech_prompt('24000000-0000-4000-8000-000000000005',gen_random_uuid(),'Where is the station?','Station meaning'),false,'Stale checkpoint token rejected');
select ok(checkpoint_speech_prompt('24000000-0000-4000-8000-000000000005',(select (v->>'lease_token')::uuid from speech_fixture where k='claim'),'Where is the station?','Station meaning'),'Checkpoint persists generated sentence before upload');
select ok(checkpoint_speech_prompt('24000000-0000-4000-8000-000000000005',(select (v->>'lease_token')::uuid from speech_fixture where k='claim'),'Where is the station?','Station meaning'),'Checkpoint replay accepted');
select throws_ok($$select checkpoint_speech_prompt('24000000-0000-4000-8000-000000000005',(select (v->>'lease_token')::uuid from speech_fixture where k='claim'),'Different sentence','Station meaning')$$,'P0001','LEARNING_CONFLICT','Retry cannot change checkpoint sentence');
reset role;
set local role authenticated;
select learning_speech_command(jsonb_build_object('action','DELETE','requestId',gen_random_uuid(),'id','24000000-0000-4000-8000-000000000005'));
reset role;
set local role service_role;
select is(finish_speech_job('24000000-0000-4000-8000-000000000005',(select (v->>'lease_token')::uuid from speech_fixture where k='claim'),null,'PROVIDER_ERROR'),false,'Delete invalidates in-flight worker');
reset role;
insert into learning_private.job_requests(user_id,kind) select '24000000-0000-4000-8000-000000000001','SPEECH_PROMPT' from generate_series(1,49);
set local role authenticated;
select throws_ok($$select learning_speech_command((select v||jsonb_build_object('id',gen_random_uuid(),'requestId',gen_random_uuid()) from speech_fixture where k='prompt'))$$,'P0001','LEARNING_LIMIT','Prompt daily limit cannot be bypassed by direct RPC');
reset role;
insert into learning_private.job_requests(user_id,kind) select '24000000-0000-4000-8000-000000000001','SPEECH_RECORDING' from generate_series(1,99);
set local role authenticated;
select throws_ok($$select begin_speech_upload(gen_random_uuid(),'24000000-0000-4000-8000-000000000003',null,'','audio/webm',100,repeat('a',64))$$,'P0001','LEARNING_LIMIT','Recording daily limit enforced at begin');
reset role;
delete from learning_private.job_requests where user_id='24000000-0000-4000-8000-000000000001';
set local role authenticated;
select begin_speech_upload(gen_random_uuid(),'24000000-0000-4000-8000-000000000003',null,'','audio/webm',100,repeat('a',64)) from generate_series(1,3);
select throws_ok($$select begin_speech_upload(gen_random_uuid(),'24000000-0000-4000-8000-000000000003',null,'','audio/webm',100,repeat('a',64))$$,'P0001','LEARNING_LIMIT','Concurrency counts pending uploads and cannot exceed three');
reset role;
update learning_speech set status='FAILED',attempts=3 where status='UPLOADING';
set local role authenticated;
select throws_ok($$select learning_speech_command(jsonb_build_object('action','RETRY','requestId',gen_random_uuid(),'id',(select id from learning_speech where status='FAILED' and attempts=3 limit 1)))$$,'P0001','LEARNING_CONFLICT','Attempt ceiling rejects retry directly at RPC');
reset role;
select * from finish();
rollback;
